  let current: ListNode<T> | null = head;
  let next: ListNode<T> | null = null;

  while (current !== null) {
    next = current.next;      // 1. Store next node
    current.next = prev;      // 2. Reverse the pointer
    prev = current;           // 3. Advance prev
    current = next;           // 4. Advance current
