/**
 * Creates a debounced version of the provided function that delays
 * invoking it until after `delay` milliseconds have elapsed since
 * the last time it was called.
 *
 * @param {Function} func - The function to debounce
 * @param {number} delay - The delay in milliseconds
 * @returns {Function} The debounced function (with a .cancel() method)
 */
function debounce(func, delay) {
  let timeoutId = null;

  function debounced(...args) {
    // Clear any existing pending invocation
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    // Set up a new delayed invocation
    // Capture `this` context so the debounced function
    // works correctly as a method
    const context = this;

    timeoutId = setTimeout(() => {
      func.apply(context, args);
      timeoutId = null;
    }, delay);
  }

  // Provide a way to cancel a pending invocation
  debounced.cancel = function () {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  // Provide a way to immediately invoke and cancel pending
  debounced.flush = function (...args) {
    debounced.cancel();
    func.apply(this, args);
  };

  return debounced;
}
